look.customCSS:
/* ───── 吐司 · 第一批 ───── */
[data-wk="chat"]{background:radial-gradient(circle at 20% 30%,rgba(233,182,110,.08),transparent 40%),#FAF5EC !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：奶油底，底下一条细线（不做框） */
[data-wk="chathead"]{background:#FAF5EC !important;border-bottom:none !important;box-shadow:0 1px 0 #EFE4D2 !important;gap:6px !important}
[data-wk="headink"],[data-wk="headink"] *{color:#5A3E26 !important}
[data-wk="headname"] > [data-wk="headink"]{font-weight:700 !important;letter-spacing:.08em !important}
[data-wk="headdim"]{color:#B5A48E !important;white-space:nowrap !important}
[data-wk="chatback"],[data-wk="chatback"] *{color:#5A3E26 !important}
[data-wk="chatback"] svg,[data-wk="headdim"] svg{stroke:#5A3E26 !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"],[data-wk="chathead"] button:has(> [data-wk="headname"]){flex:1 1 auto !important;min-width:0 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:34px !important;min-width:34px !important;height:34px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 头像：一个荷包蛋，头像就是蛋黄（描一圈蛋黄色） */
button[data-wk="avatar"],span[data-wk="avatar"]{position:relative !important;overflow:visible !important;isolation:isolate !important;border-radius:50% !important;box-shadow:0 0 0 2.5px #FFC93C !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{position:relative !important;z-index:1 !important;border-radius:50% !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;inset:-34% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:-1 !important;pointer-events:none !important;filter:drop-shadow(0 2px 3px rgba(140,100,60,.15)) !important}
[data-wk="chathead"] button[data-wk="avatar"]::before,[data-wk="chathead"] span[data-wk="avatar"]::before{content:none !important}
[data-wk="msg"] [data-wk="row"]{gap:14px !important}

/* 气泡：一片吐司——一圈烤黄的面包边，顶上一个比身子略宽、中间鼓起的面包顶 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border:3px solid #B87A3E !important;border-top:none !important;border-radius:0 0 12px 12px !important;padding:6px 18px 10px !important;margin-top:22px !important;color:#5A3E26 !important;letter-spacing:.06em !important;box-shadow:0 3px 6px rgba(140,100,60,.12) !important}
[data-wk="bubble"][data-kind="text"]::before{content:"" !important;position:absolute !important;left:-8px !important;right:-8px !important;top:-22px !important;height:24px !important;background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;border:none !important;transform:none !important;bottom:auto !important;width:auto !important}
[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#FFFCF5 !important}
/* 我的：烤过的金黄吐司，右边抹一块黄油 */
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(180deg,#E9B66E,#DFA45A) !important;padding-right:38px !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{content:"" !important;position:absolute !important;right:10px !important;top:50% !important;width:20px !important;height:18px !important;margin-top:-10px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;transform:rotate(-8deg) !important;left:auto !important;bottom:auto !important}

/* 时间：一行淡棕小字 */
[data-wk="time"] > span{background:transparent !important;border:none !important;box-shadow:none !important;color:#B5A48E !important;letter-spacing:.15em !important;font-size:11.5px !important}
/* 已读＝后面一颗焦糖色小点；已送达＝浅灰小点 */
[data-wk="meta"]{color:#B5A48E !important;font-size:10.5px !important;letter-spacing:.1em !important;display:inline-flex !important;align-items:center !important;gap:6px !important}
[data-wk="meta"]::after{content:"" !important;width:8px !important;height:8px !important;flex:none !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMCAxMCc+PGNpcmNsZSBjeD0nNScgY3k9JzUnIHI9JzMuMicgZmlsbD0nI0Q5Q0NCOCcvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="meta"][data-read="1"]::after{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMCAxMCc+PGNpcmNsZSBjeD0nNScgY3k9JzUnIHI9JzMuMicgZmlsbD0nI0I4N0EzRScvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:#FFFCF5 !important;border:3px solid #B87A3E !important;border-radius:12px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#B87A3E !important}
[data-wk="name"]{color:#B5A48E !important}

/* 动描：没有框，棕色斜体，左边一道虚线（像撒的面包屑） */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{background:transparent !important;border:none !important;border-left:2px dotted #B87A3E !important;border-radius:0 !important;box-shadow:none !important;color:#8E7258 !important;font-style:italic !important;font-size:13px !important;line-height:1.8 !important;padding:2px 0 2px 14px !important}
/* 系统提示：一行小字 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#B5A48E !important;font-size:11px !important;font-style:normal !important;letter-spacing:.08em !important}

/* 底栏：白底一条，输入框浅灰胶囊；加号、发送是细圈，最右「让他回复」是焦糖色圆钮 */
[data-wk="composer"]{background:#fff !important;border-top:none !important;box-shadow:0 -1px 0 #EFE4D2,0 -4px 12px rgba(140,100,60,.05) !important;align-items:center !important;gap:10px !important}
[data-wk="chatinput"]{background:#F5F1EA !important;border:none !important;border-radius:12px !important;color:#5A3E26 !important}
[data-wk="chatinput"]::placeholder{color:#BFB3A2 !important}
[data-wk="chatplus"],[data-wk="send"],[data-wk="chatreply"]{border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{width:34px !important;min-width:34px !important;height:34px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="send"]{width:34px !important;min-width:34px !important;height:34px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:44px !important;min-width:44px !important;height:44px !important;border-radius:50% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.9) !important}
[data-wk="chatpanel"]{background:#fff !important;border-top:1px solid #EFE4D2 !important}
[data-wk="quotedraft"]{position:relative !important;z-index:3 !important}
